import { createPrivateWeakStore } from "../security/private-weak-store.js";
const identities = createPrivateWeakStore();
/** Retain stream identity internally without adding private metadata to UI schemas. */
export function bindReasoningPartIdentity(part, id, open) {
    identities.set(part, { id, open });
    return part;
}
export function readReasoningPartIdentity(part) {
    return identities.get(part);
}
